def recovery_transition(state,expected_epoch,action,evidence):
    # Own immutable state:(epoch,phase);trusted observation flags are toy inputs.
    if type(state) is not tuple or len(state)!=2 or type(state[0]) is not int or state[0]<0 or state[1] not in ('running','paused','reconciling','ready'):
        raise ValueError('invalid recovery state')
    if type(expected_epoch) is not int or expected_epoch!=state[0]:raise ValueError('stale recovery epoch')
    if type(action) is not str or action not in ('pause','inspect','approve','resume'):raise ValueError('invalid recovery action')
    if type(evidence) is not dict or set(evidence)!={'snapshot_current','invariants_ok','unknown_effects'} or any(type(x) is not bool for x in evidence.values()):raise ValueError('invalid recovery evidence')
    phase=state[1]
    if action=='pause' and phase=='running':new='paused'
    elif action=='inspect' and phase=='paused':new='reconciling'
    elif action=='approve' and phase=='reconciling' and evidence['snapshot_current'] and evidence['invariants_ok'] and not evidence['unknown_effects']:new='ready'
    elif action=='resume' and phase=='ready' and evidence['snapshot_current'] and evidence['invariants_ok'] and not evidence['unknown_effects']:new='running'
    else:raise ValueError('unsafe or out-of-order recovery transition')
    return state[0]+1,new

e={'snapshot_current':True,'invariants_ok':True,'unknown_effects':False}
state=(0,'running')
for action in ('pause','inspect','approve','resume'):
    state=recovery_transition(state,state[0],action,e);print(state)
try:recovery_transition(state,0,'pause',e)
except ValueError as error:print(error)
try:recovery_transition((2,'reconciling'),2,'approve',{**e,'unknown_effects':True})
except ValueError as error:print(error)
